package com.voicetxt.reader;

import android.app.Instrumentation;import android.os.*;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;

/** Comparable native startup measurements before/after the first-phase changes. No preferences are changed. */
public class VoiceStartupBenchmark extends Instrumentation {
    static final String TEXT="夜幕渐渐降临在宁静的山谷，远处的灯火映着缓缓流动的河水，我们沿着小路向前走去，听着晚风轻轻吹过树梢，心里感到十分平静。\n清晨的第一缕阳光照进房间，书页上的文字也变得温暖起来。\n她拿起桌边的书，继续读着昨天没有读完的故事。\n窗外传来清脆的鸟鸣声，新的一天就这样开始了。";
    public void onCreate(Bundle state){super.onCreate(state);start();}
    static List<String> chunks(){ArrayList<String> result=new ArrayList<>();for(int at=0;at<TEXT.length();){int end=SpeechSegmenter.end(TEXT,at,TEXT.length());if(result.isEmpty())try{java.lang.reflect.Method first=SpeechSegmenter.class.getDeclaredMethod("firstEnd",String.class,int.class,int.class);end=(Integer)first.invoke(null,TEXT,at,end);}catch(ReflectiveOperationException ignored){}String value=TEXT.substring(at,end);if(!value.trim().isEmpty())result.add(value);at=end;}return result;}
    public void onStart(){Bundle result=new Bundle();ArrayList<VoiceModel> selected=new ArrayList<>();VoicePackages store=VoicePackages.get(getTargetContext());for(String wanted:new String[]{"eula","chaowen","huayan"})for(VoiceModel pack:store.list("zh"))if(pack.name.contains(wanted)&&!pack.name.contains("fp16")){selected.add(pack);break;}boolean success=false;JSONArray metrics=new JSONArray();
        try{if(selected.isEmpty())throw new AssertionError("No installed speech models");
            for(VoiceModel pack:selected){PackageSpeaker speaker=new PackageSpeaker(getTargetContext(),new VoicePackages.Selection(pack,pack.name.contains("eula")&&pack.speakers>73?73:0),"zh");try{CountDownLatch loaded=new CountDownLatch(1),done=new CountDownLatch(1);AtomicReference<Throwable> failure=new AtomicReference<>();long init=SystemClock.elapsedRealtime();speaker.init(error->{failure.set(error);loaded.countDown();});if(!loaded.await(40,TimeUnit.SECONDS)||failure.get()!=null)throw new AssertionError("Model failed to load",failure.get());long loadMs=SystemClock.elapsedRealtime()-init;AtomicLong first=new AtomicLong();AtomicInteger count=new AtomicInteger();long requested=SystemClock.elapsedRealtime();List<String> lines=chunks();speaker.speakSequence(lines,0,1.8f,new OfflineSpeaker.SequenceListener(){public void buffering(int ready){}public void sentence(int index){first.compareAndSet(0,SystemClock.elapsedRealtime()-requested);count.incrementAndGet();}public void done(){done.countDown();}public void failed(Throwable error){failure.set(error);done.countDown();}});if(!done.await(100,TimeUnit.SECONDS)||failure.get()!=null||count.get()!=lines.size())throw new AssertionError("Speech incomplete: "+pack.name,failure.get());JSONObject row=new JSONObject().put("model",pack.name).put("loadMs",loadMs).put("firstAudioAfterReadyMs",first.get()).put("coldTotalMs",loadMs+first.get()).put("chunks",lines.size()).put("firstChars",lines.get(0).length()).put("underruns",speaker.sequenceUnderruns).put("endUnderruns",speaker.sequenceEndUnderruns);try{Object timing=OfflineSpeaker.class.getDeclaredField("lastTiming").get(speaker);row.put("timing",String.valueOf(timing.getClass().getDeclaredMethod("json").invoke(timing)));}catch(ReflectiveOperationException ignored){}metrics.put(row);Bundle progress=new Bundle();progress.putString("modelResult",row.toString());sendStatus(1,progress);}finally{speaker.close();}}
            result.putString("metrics",metrics.toString());result.putString("result","PASS: installed Eula/Piper models measured; all sentences spoken in order; no changes to books, voices or preferences");success=true;
        }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));result.putString("metrics",metrics.toString());}finish(success?-1:0,result);
    }
}
